    inspected={'curriculum/modules/T47.md':['Complete module teaching, contracts, study and limits'], 'labs/storage/include/store.h':['Complete API and typed core representation'],'labs/storage/FORMAT.md':['Complete CST2 representation and persistence contract'],'labs/storage/INTEGRATION.md':['Complete block/VM boundaries and execution obligations'],'assessor/storage/store.c':['Complete codec, cache, tree mutation/traversal, transaction, WAL, checkpoint, recovery and integrity implementation'],'labs/storage/tests/test_store.c':['Complete retained component, differential, failure-cut, file and VM harness'],'labs/storage/src/store_file.c':['Complete actual POSIX page-transfer/flush/open/close adapter'],'labs/storage/include/store_file.h':['Complete adapter ownership API'],'labs/storage/CMakeLists.txt':['Actual C17 baseline, imports, selected tests and three compiled mutants']}
